Hmmm, below is an example for base game where I made show choices window show line of text ('TEST') and then the choices below that. So I added itemHeight to the heights and itemRect (edit: itemRect y) and then made it draw the base text in drawAllItems. Hope I'm not forgetting anything.
For your question in the edit, are you sure you remembered to deactivate the "parent window"? Else it'll keep reading your inputs I think.
Window_ChoiceList.prototype.windowHeight = function() {
return this.fittingHeight(this.numVisibleRows()) + this.itemHeight();
};
Window_ChoiceList.prototype.contentsHeight = function() {
return this.maxItems() * this.itemHeight() + this.itemHeight();
};
Window_ChoiceList.prototype.itemRect = function(index) {
var rect = new Rectangle();
var maxCols = this.maxCols();
rect.width = this.itemWidth();
rect.height = this.itemHeight();
rect.x = index % maxCols * (rect.width + this.spacing()) - this._scrollX;
rect.y = Math.floor(index / maxCols) * rect.height - this._scrollY + this.itemHeight();
return rect;
};
Window_ChoiceList.prototype.drawAllItems = function() {
this.drawText('TEST', 0, 0, this.itemWidth(), 'center');
var topIndex = this.topIndex();
for (var i = 0; i < this.maxPageItems(); i++) {
var index = topIndex + i;
if (index < this.maxItems()) {
this.drawItem(index);
}
}
};

